using BetaFit.Desktop.Models; using BetaFit.Desktop.Services;
namespace BetaFit.Desktop.Forms;
public partial class FrmLogin:Form { private readonly IBetaFitApiService _api;private readonly Session _session; public FrmLogin(IBetaFitApiService api,Session session){_api=api;_session=session;InitializeComponent();btnLogin.Click+=async(_,_)=>await LoginAsync();} private async Task LoginAsync(){lblError.Text="";if(string.IsNullOrWhiteSpace(txtEmail.Text)||string.IsNullOrWhiteSpace(txtPassword.Text)){lblError.Text="Informe e-mail e senha.";return;}try{btnLogin.Enabled=false;var r=await _api.LoginAsync(new LoginRequest{Email=txtEmail.Text.Trim(),Password=txtPassword.Text});if(!string.Equals(r.Role,"Admin",StringComparison.OrdinalIgnoreCase)){lblError.Text="Esta conta não possui acesso administrativo.";return;}_session.SignIn(r);DialogResult=DialogResult.OK;Close();}catch(Exception ex){lblError.Text=ex.Message;}finally{btnLogin.Enabled=true;}} }